<template>
<section class="screen"><header class="page-header"><div><p class="eyebrow">WORKSPACE / RUNTIMES</p><h1>Runtimes</h1><p class="subtitle">Versions available to your local projects.</p></div><button class="primary-button" @click="packageBrowser?.show()">+ Add runtime</button></header><div class="runtime-layout"><article class="panel runtime-list-panel"><div class="list-heading runtime-heading"><span>Runtime</span><span>Version</span><span>Projects</span><span>Status</span></div><button v-for="runtime in runtimeController.runtimes" :key="runtime.name" class="runtime-item" :class="{ selected: selectedRuntime?.name === runtime.name }" @click="runtimeController.select(runtime)"><span class="runtime-primary"><span class="runtime-mark">{{ runtime.name.slice(0,1) }}</span><span><b>{{ runtime.name }}</b><small>{{ runtime.family }}</small></span></span><code>{{ runtime.version }}</code><span class="runtime-projects">{{ runtime.projects }}</span><span class="state-label">{{ runtime.state === 'active' ? 'Installed' : 'Available' }}</span></button></article><article v-if="selectedRuntime" class="panel runtime-detail-panel"><div class="detail-top"><div><p class="eyebrow">RUNTIME DETAIL</p><h2>{{ selectedRuntime.name }}</h2><p class="detail-kind">{{ selectedRuntime.family }} · <code>{{ selectedRuntime.version }}</code></p></div><span class="runtime-mark runtime-mark--large">{{ selectedRuntime.name.slice(0,1) }}</span></div><div class="runtime-facts"><div><span>Install path</span><code>{{ selectedRuntime.path }}</code></div><div><span>Assigned projects</span><b>{{ selectedRuntime.projects }}</b></div></div><div v-if="selectedRuntime.name==='PHP'" class="runtime-tools"><div class="detail-actions"><button class="action-button" :disabled="php.state.loading" @click="php.load()">{{ php.state.loading ? 'Reading PHP…' : 'Refresh PHP details' }}</button><button class="action-button" @click="php.openFolder()">Open PHP folder</button></div><p v-if="php.state.error" class="forge-alert forge-alert--error">{{ php.state.error }}</p><div class="runtime-facts"><div><span>php.ini</span><code>{{ php.state.iniPath || 'Not loaded' }}</code></div><div><span>Loaded extensions</span><b>{{ php.state.extensions.length }}</b></div></div><div class="extension-pills"><span v-for="name in php.state.extensions" :key="name">{{ name }}</span></div></div><PackageBrowser v-if="selectedFlag" ref="packageBrowser" :key="selectedFlag" :flag="selectedFlag" :title="selectedRuntime.name" /></article></div></section>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { runtimeController } from '../state/runtimeController'; import PackageBrowser from '../components/PackageBrowser.vue'; import { phpController } from '../state/phpController';
const packageBrowser=ref<InstanceType<typeof PackageBrowser>>(); const selectedRuntime=computed(()=>runtimeController.selected.runtime); const flags:Record<string,string>={PHP:'php','Node.js':'node',Python:'python',Go:'golang',Java:'java',Ruby:'ruby',Rust:'rust',Bun:'bun',Deno:'deno','.NET':'dotnet',Erlang:'erlang',Perl:'perl',Zig:'zig',Flutter:'flutter',Gradle:'gradle'}; const selectedFlag=computed(()=>selectedRuntime.value?flags[selectedRuntime.value.name]:undefined); const php=phpController; onMounted(()=>{runtimeController.refresh().catch()});
</script>
